import logging
import select
import socket


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class DataExchange(object):

    def __init__(self, remote_service):
        self._remote_service = remote_service

    def forwarding_handler(self, channel):
        sock = socket.socket()
        host, port = self._remote_service.address.host, self._remote_service.address.port
        try:
            sock.connect((host, port))
        except Exception as e:
            logging.debug("Forwarding request to %s:%d failed: %r" % (host, port, e))
            return

        logging.debug("Connected!  Tunnel open %r -> %r -> %r" % (channel.origin_addr, channel.getpeername(), (host, port)))

        while True:
            r, _, _ = select.select([sock, channel], [], [])
            if sock in r:
                data = sock.recv(1024)
                if not data:
                    break
                channel.send(data)
            if channel in r:
                data = channel.recv(1024)
                if not data:
                    break
                sock.send(data)
        channel.close()
        sock.close()
        logging.debug("Tunnel closed from %r" % (channel.origin_addr,))
